package com.mechanical.worldgen;

import com.mechanical.Mechanical;
import com.mojang.serialization.MapCodec;

import net.minecraft.core.registries.Registries;
import net.minecraft.world.level.levelgen.feature.Feature;
import net.neoforged.neoforge.registries.DeferredRegister;

/**
 * Small Stone Age worldgen structures, built block by block by Java features so they adapt to the terrain.
 * Placement (rarity, biomes) is data, generated by scripts/gen_structures.py.
 */
public final class Structures {
    public static final DeferredRegister<MapCodec<? extends Feature>> FEATURE_TYPES = DeferredRegister.create(Registries.FEATURE_TYPE, Mechanical.MODID);
    /** Thin old bones for the bone remains, sand skeletons and mammoth tusks (OldBonesBlock; models: scripts/gen_land_decor.py). */
    public static final net.neoforged.neoforge.registries.DeferredBlock<OldBonesBlock> RIB_CAGE = Mechanical.BLOCKS.registerBlock("rib_cage",
            p -> new OldBonesBlock(false, p), p -> p.mapColor(net.minecraft.world.level.material.MapColor.SAND).strength(0.6F)
                    .sound(net.minecraft.world.level.block.SoundType.BONE_BLOCK).noOcclusion()
                    .pushReaction(net.minecraft.world.level.material.PushReaction.POPPED));
    public static final net.neoforged.neoforge.registries.DeferredBlock<OldBonesBlock> MAMMOTH_TUSK = Mechanical.BLOCKS.registerBlock("mammoth_tusk",
            p -> new OldBonesBlock(true, p), p -> p.mapColor(net.minecraft.world.level.material.MapColor.TERRACOTTA_WHITE).strength(1.0F)
                    .sound(net.minecraft.world.level.block.SoundType.BONE_BLOCK).noOcclusion()
                    .pushReaction(net.minecraft.world.level.material.PushReaction.POPPED));
    /** The wood ants' mound for OpenDecor.anthill (AnthillBlock; models and texture: scripts/gen_land_decor.py). */
    public static final net.neoforged.neoforge.registries.DeferredBlock<AnthillBlock> ANTHILL = Mechanical.BLOCKS.registerBlock("anthill",
            AnthillBlock::new, p -> p.mapColor(net.minecraft.world.level.material.MapColor.PODZOL).strength(0.5F)
                    .sound(net.minecraft.world.level.block.SoundType.ROOTED_DIRT).noOcclusion());

    static {
        FEATURE_TYPES.register("abandoned_campsite", () -> AbandonedCampsite.CODEC);
        FEATURE_TYPES.register("hunters_lean_to", () -> HuntersLeanTo.CODEC);
        FEATURE_TYPES.register("bear_den", () -> BearDen.CODEC);
        FEATURE_TYPES.register("standing_stones", () -> StandingStones.CODEC);
        FEATURE_TYPES.register("burial_mound", () -> BurialMound.CODEC);
        FEATURE_TYPES.register("fishing_camp", () -> FishingCamp.CODEC);
        FEATURE_TYPES.register("flint_quarry", () -> FlintQuarry.CODEC);
        FEATURE_TYPES.register("mammoth_bone_hut", () -> MammothBoneHut.CODEC);
        FEATURE_TYPES.register("hermits_hut", () -> HermitsHut.CODEC);
        // small decorations (scripts/gen_decorations.py)
        FEATURE_TYPES.register("glacial_erratic", Boulder.ERRATIC::codec);
        // berry thickets (scripts/gen_flora.py)
        for (ThicketFeature f : ThicketFeature.ALL) FEATURE_TYPES.register(f.kind + "_thicket", f::codec);
        FEATURE_TYPES.register("mossy_boulder", Boulder.MOSSY::codec);
        FEATURE_TYPES.register("sandstone_boulder", Boulder.SANDSTONE::codec);
        FEATURE_TYPES.register("glacial_boulder", Boulder.GLACIAL::codec); // scripts/gen_world_biomes.py
        FEATURE_TYPES.register("cairn", () -> Cairn.CODEC);
        FEATURE_TYPES.register("balanced_rock", () -> BalancedRock.CODEC);
        FEATURE_TYPES.register("rune_stone", () -> RuneStone.CODEC);
        FEATURE_TYPES.register("stone_head", () -> StoneHead.CODEC);
        FEATURE_TYPES.register("animal_carving", () -> AnimalCarving.CODEC);
        FEATURE_TYPES.register("shrine_statue", () -> ShrineStatue.CODEC);
        FEATURE_TYPES.register("trail", () -> Trails.CODEC);
        FEATURE_TYPES.register("smooth_ground", () -> SmoothGround.CODEC); // scripts/gen_dirt_slab.py
        FEATURE_TYPES.register("bog_oak_logs", () -> BogOakLogs.CODEC); // scripts/gen_earth.py
        FEATURE_TYPES.register("glimmering_stump", () -> GlimmeringStumpFeature.CODEC); // scripts/gen_folklore.py
        FEATURE_TYPES.register("troll_stone_sleeper", () -> TrollStoneSleeperFeature.CODEC); // scripts/gen_folklore.py
        FEATURE_TYPES.register("cave_paintings", CaveFinds.PAINTINGS::codec); // scripts/gen_caves.py
        FEATURE_TYPES.register("tool_cache", CaveFinds.TOOL_CACHE::codec);
        // forest floor and waterside (scripts/gen_nature_decor.py)
        FEATURE_TYPES.register("fallen_log", ForestDecor.FALLEN_LOG::codec);
        FEATURE_TYPES.register("snag", ForestDecor.SNAG::codec);
        FEATURE_TYPES.register("root_plate", ForestDecor.ROOT_PLATE::codec);
        FEATURE_TYPES.register("mossy_stones", ForestDecor.MOSSY_STONES::codec);
        FEATURE_TYPES.register("log_bridge", WaterDecor.LOG_BRIDGE::codec);
        FEATURE_TYPES.register("beaver_dam", WaterDecor.BEAVER_DAM::codec);
        FEATURE_TYPES.register("driftwood", WaterDecor.DRIFTWOOD::codec);
        FEATURE_TYPES.register("gravel_bar", WaterDecor.GRAVEL_BAR::codec);
        FEATURE_TYPES.register("reed_belt", WaterDecor.REED_BELT::codec);
        FEATURE_TYPES.register("hillside_spring", WaterDecor.SPRING::codec);
        // mountains, open ground, dry and cold land (scripts/gen_land_decor.py)
        FEATURE_TYPES.register("talus", MountainDecor.TALUS::codec);
        FEATURE_TYPES.register("fallen_rock", MountainDecor.FALLEN_ROCK::codec);
        FEATURE_TYPES.register("rock_arch", MountainDecor.ROCK_ARCH::codec);
        FEATURE_TYPES.register("bird_cliff", MountainDecor.BIRD_CLIFF::codec);
        FEATURE_TYPES.register("valley_waterfall", MountainDecor.WATERFALL::codec);
        FEATURE_TYPES.register("snow_patch", MountainDecor.SNOW_PATCH::codec);
        FEATURE_TYPES.register("rock_outcrop", OpenDecor.OUTCROP::codec);
        FEATURE_TYPES.register("bone_remains", OpenDecor.BONES::codec);
        FEATURE_TYPES.register("anthill", OpenDecor.ANTHILL::codec);
        FEATURE_TYPES.register("lone_tree", OpenDecor.LONE_TREE::codec);
        FEATURE_TYPES.register("farm_walls", OpenDecor.FARM_WALLS::codec);
        FEATURE_TYPES.register("fire_ring", OpenDecor.FIRE_RING::codec);
        FEATURE_TYPES.register("root_cellar", OpenDecor.ROOT_CELLAR::codec);
        FEATURE_TYPES.register("dead_tree", DryColdDecor.DEAD_TREE::codec);
        FEATURE_TYPES.register("sand_skeleton", DryColdDecor.SAND_SKELETON::codec);
        FEATURE_TYPES.register("rock_overhang", DryColdDecor.OVERHANG::codec);
        FEATURE_TYPES.register("dry_creek", DryColdDecor.DRY_CREEK::codec);
        FEATURE_TYPES.register("ice_blocks", DryColdDecor.ICE_BLOCKS::codec);
        FEATURE_TYPES.register("frost_split", DryColdDecor.FROST_SPLIT::codec);
        FEATURE_TYPES.register("mammoth_tusks", DryColdDecor.MAMMOTH_TUSKS::codec);
        FEATURE_TYPES.register("charred_tree", () -> ScorchedBarrens.CharredTree.CODEC); // scripts/gen_world_biomes.py
        FEATURE_TYPES.register("burnt_forest", BurntForest.INSIDE::codec);
        FEATURE_TYPES.register("burnt_forest_edge", BurntForest.OUTSIDE::codec);
    }

    public static void init() {}

    private Structures() {}
}
